/**
 * RegionAndCultureComboBox is the combo box used to set 'Region and Culture' in Preferences > Localization.
 *
 * @author Jesse Greenberg (PhET Interactive Simulations)
 */

import { string_joist_preferences_tabs_localization_regionAndCulture_africa_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/africa.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_africaModest_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/africaModest.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_asia_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/asia.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_latinAmerica_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/latinAmerica.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_oceania_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/oceania.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_random_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/random.js';
import { string_joist_preferences_tabs_localization_regionAndCulture_unitedStatesOfAmerica_StringProperty } from '../strings/preferences/tabs/localization/regionAndCulture/unitedStatesOfAmerica.js';
import '../../../globals.js';
import type LocalizedStringProperty from '../../../chipper/js/browser/LocalizedStringProperty.js';
import optionize, { type EmptySelfOptions } from '../../../phet-core/js/optionize.js';
import type PickOptional from '../../../phet-core/js/types/PickOptional.js';
import Text from '../../../scenery/js/nodes/Text.js';
import ComboBox, { type ComboBoxOptions } from '../../../sun/js/ComboBox.js';
import Tandem from '../../../tandem/js/Tandem.js';
import regionAndCultureProperty, { type RegionAndCulture, supportedRegionAndCultureValues } from '../i18n/regionAndCultureProperty.js';
import joist from '../joist.js';
import PreferencesDialogConstants from './PreferencesDialogConstants.js';

// Maps a RegionAndCulture value to a StringProperty.
const STRING_PROPERTY_MAP: Record<RegionAndCulture, LocalizedStringProperty> = {
  africa: string_joist_preferences_tabs_localization_regionAndCulture_africa_StringProperty,
  africaModest: string_joist_preferences_tabs_localization_regionAndCulture_africaModest_StringProperty,
  asia: string_joist_preferences_tabs_localization_regionAndCulture_asia_StringProperty,
  latinAmerica: string_joist_preferences_tabs_localization_regionAndCulture_latinAmerica_StringProperty,
  oceania: string_joist_preferences_tabs_localization_regionAndCulture_oceania_StringProperty,
  random: string_joist_preferences_tabs_localization_regionAndCulture_random_StringProperty,
  usa: string_joist_preferences_tabs_localization_regionAndCulture_unitedStatesOfAmerica_StringProperty
};

type SelfOptions = EmptySelfOptions;
type RegionAndCultureComboBoxOptions = SelfOptions & PickOptional<ComboBoxOptions, 'tandem'>;

class RegionAndCultureComboBox extends ComboBox<RegionAndCulture> {

  public constructor( providedOptions?: RegionAndCultureComboBoxOptions ) {

    const options = optionize<RegionAndCultureComboBoxOptions, SelfOptions, ComboBoxOptions>()( {

      // For now, do not instrument Preferences elements, see https://github.com/phetsims/joist/issues/744#issuecomment-1196028362
      tandem: Tandem.OPT_OUT
    }, providedOptions );

    // Sort the region and culture choices. We are sorting on RegionAndCulture tokens, rather than translated strings,
    // because ComboBox does not have an API for changing the order of items in its listbox. Since there are a
    // relatively small number of items here, we felt that having a consistent order here was sufficient, and that
    // the effort to dynamically put the items in alphabetical order was not warranted.
    // See https://github.com/phetsims/joist/issues/955
    const comboBoxItems = supportedRegionAndCultureValues.slice().sort().map( regionAndCulture => {
      return {
        value: regionAndCulture,
        createNode: () => new Text( STRING_PROPERTY_MAP[ regionAndCulture ], PreferencesDialogConstants.PANEL_SECTION_CONTENT_OPTIONS )
      };
    } );

    // TODO: Need a different top layer node for ComboBox here. See https://github.com/phetsims/joist/issues/841
    super( regionAndCultureProperty, comboBoxItems, phet.joist.sim.topLayer, options );
  }
}

joist.register( 'RegionAndCultureComboBox', RegionAndCultureComboBox );
export default RegionAndCultureComboBox;